def check_tree_llm(node_name, temp_tree, field, node_path, name_list):
    """校验tree结构是否合理"""
    try:
        temp_prompt = CHECK_BASE_TREE_TEMPLATE.format(field=field, up_path=node_path, name_list=name_list)
        user_content = temp_tree
        llm_res = llm_chat_retry(messages=[
            {"role": "system", "content": temp_prompt},
            {"role": "user", "content": json.dumps(user_content)}],
            max_len=128000, model='gpt-4o-mini')
        if llm_res:
            return llm_res
        return {"is_valid": '1', "issues": []}
    except Exception as e:
        logger.error(f'【{node_name}】知识点下的tree校验--大模型生成失败，异常信息【{e}】：{traceback.format_exc()}')
        return {"is_valid": '1', "issues": []}


def adjust_tree_llm(node_name, temp_tree, suggestion, field, node_path, name_list):
    """调整tree结构"""
    try:
        temp_prompt = ADJUST_TREE_TEMPLATE.format(topic=node_name, field=field, up_path=node_path, name_list=name_list) + RICH_TREE_OUTPUT
        user_content = {"knowledge_tree": temp_tree, "user_issues": suggestion}
        res_llm = llm_chat_retry(messages=[
            {"role": "system", "content": temp_prompt},
            {"role": "user", "content": json.dumps(user_content)}],
            max_len=128000, model='gpt-4.1-mini')
        if res_llm:
            return res_llm
        return temp_tree
    except Exception as e:
        logger.error(f'【{node_name}】知识点下的tree进行调整--大模型生成失败，异常信息【{e}】：{traceback.format_exc()}')
        return temp_tree


def check_and_adjust_tree(node_name, temp_tree, field, node_path, name_list, retry=1, idx=1, max_depth=2):
    """校验并调整tree结构"""

    
    if retry > 0:
        check_res = check_tree_llm(node_name, temp_tree, field, node_path, name_list)

        
        if not int(check_res['is_valid']):
            suggestion = f'该主题`{node_name}`下的知识框架不合格，需要重新调整，问题与修正建议如下：\n'
            for num, item in enumerate(check_res['issues'], 1):
                suggestion += f"问题{num}: 定位到【{item['node_path']}】节点位置，{item['issue_type']}错误，{item['problem']}，"
                suggestion += f"建议{item['fix']}\n" if '建议' not in item['fix'] else f"{item['fix']}\n"

            logger.debug(f"【{node_name}】子树的第{idx}次check结果为：{suggestion}")
            print(f"【{node_name}】子树的第{idx}次check结果为：{suggestion}")

            adjust_tree = adjust_tree_llm(node_name, temp_tree, suggestion, field, node_path, name_list)
            adjust_tree['name'] = node_name  
            adjust_tree = get_level2_tree(adjust_tree, max_depth=max_depth)

            child_name_list = [child['name'] for child in adjust_tree['children']]
            logger.debug(f"【{node_name}】第{idx}次adjust后的子节点为: {child_name_list}")
            print(f"【{node_name}】第{idx}次adjust后的子节点为: {child_name_list}")

            if len(adjust_tree['children']) < 5:  
                adjust_tree = temp_tree
                logger.debug('adjust后分支过少，回退到上一次的tree')
                print('adjust后分支过少，回退到上一次的tree')

            
            if retry > 0:
                adjust_tree = check_and_adjust_tree(node_name, adjust_tree, field, node_path, name_list, retry - 1, idx + 1, max_depth)
            return adjust_tree
    return temp_tree


def get_clearn_tree(temp_tree):
    """只要tree里的name和children字段"""
    new_tree = {"name": temp_tree['name'], "children": []}
    if 'children' in temp_tree and temp_tree['children']:
        for child in temp_tree['children']:
            new_tree['children'].append(get_clearn_tree(child))
    return new_tree


