    kn_tree = get_knowledge_framework_llm(topic, field, node_path, node_name_list, max_depth)
    if kn_tree:
        kn_tree['name'] = topic
        kn_tree = get_level2_tree(kn_tree, max_depth=max_depth)
    else:
