def merge_base_rich_tree(topic, ori_node_list, node_tree, new_tree, kn_tree, field, max_width_ori, with_merge_llm=True, retry=2, idx=1):
    """基础tree与拓展tree的融合"""
    merge_tree = {}
    
    
    
    
    
    if with_merge_llm:
        if new_tree:
            merge_tree = merge_base_tree_llm(topic, node_tree, new_tree, field)
        elif kn_tree:
            merge_tree = merge_base_tree_llm(topic, node_tree, kn_tree, field)
        if merge_tree:
            merge_tree['name'] = topic
    
    if not merge_tree or len(merge_tree.get('children', [])) <= 5:
        merge_tree = copy.deepcopy(node_tree)
        merge_tree['children'].extend(new_tree.get('children', kn_tree.get('children', [])))

    child_name_list = [child['name'] for child in merge_tree['children']]
    n_child = len(child_name_list)

    logger.debug(f"【{topic}】第{idx}次融合后的子节点为: {child_name_list}")
    print(f"【{topic}】第{idx}次融合后的子节点为: {child_name_list}")

    if n_child - max_width_ori < 2 and retry > 1:  
        merge_tree = merge_base_rich_tree(topic, ori_node_list, node_tree, new_tree, kn_tree, field, max_width_ori, with_merge_llm, retry-1, idx+1)

    
    
    
    
    
    
    return merge_tree


