def process_subtrees(nodes, ori_tree, field, root_name, max_depth):
    """线程池处理子树"""
    task_to_node = {}
    with ThreadPoolExecutor(max_workers=min(len(nodes), 4)) as executor:
        for node in nodes:
            task = executor.submit(process_single_node, node, field, root_name, ori_tree, max_depth)
            task_to_node[task] = node
        for task in as_completed(task_to_node.keys()):
            res = task.result()
            node = task_to_node[task]
            if res:
                node['children'] = res['children']


