    param_dict = {"aliases": [], "description": "", "type": 0, "labels": [], "parent_relation": "",
                  "parent_relation_desc": "", "sourceList": [], "children": []}
    
    base_name_list = [node['name']for node in get_node_list(base_tree)]
    task_dict = {}
    with tqdm(total=len(node_list), desc="Rich_add_tree", mininterval=2) as pbar:
        for node in node_list:
            if node.get('children', []):
                continue
            task = GEN_TOPIC_SUBTREE_POOL.submit(gen_add_node_subtree_llm, node, base_name_list, field, max_depth)
            task_dict[task] = node
        for task in as_completed(task_dict.keys()):
            node = task_dict[task]
            res = task.result()
            if res:
                for param, v in param_dict.items():
                    node[param] = res.get(param, v)
            tag_base_tree(node, tag='add')
            pbar.update(1)  


