def _transform_source(source, resource_dict):
    """转换单个 source 对象"""
    if len(list(source.keys())) != 3:
        return source

    
    base_source = {
        "title": "",
        "sourceId": source['uid'],
        "sourceName": source['name'],
        "sourceType": "url" if source['url'] else '',
        "id": -1,
        "segId": -1,
        "url": source['url'],
    }

    if not resource_dict:
        return base_source

    
    uid = get_md5_id(source['name'] + source['url'] + source['uid'])
    mapped_source = resource_dict.get(uid)

    if mapped_source:
        new_source = mapped_source.copy()
        new_source.pop('name', None)
        return new_source
    else:
        return base_source


